package com.fasterxml.jackson.databind.node;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.databind.JsonSerializable;
import com.fasterxml.jackson.databind.SerializerProvider;
import com.fasterxml.jackson.databind.annotation.JsonSerialize;
import com.fasterxml.jackson.databind.util.RawValue;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class POJONode_serialize_TriageGen2Test {

    /**
     * Mock interface to simulate the JsonSerializable condition.
     */
    public interface JsonSerializable {
        void serialize(JsonGenerator gen, SerializerProvider ctxt) throws IOException;
    }

    /**
     * Mock class to represent a standard POJO.
     */
    public static class TestPojo {
        public String name = "test";
    }

    @Test
    public void testSerialize_withNullValue() throws IOException {
        // Arrange
        POJONode node = new POJONode(null);
        JsonGenerator gen = mock(JsonGenerator.class);
        SerializerProvider ctxt = mock(SerializerProvider.class);

        // Act
        node.serialize(gen, ctxt);

        // Assert
        verify(ctxt).defaultSerializeNull(gen);
        verifyNoMoreInteractions(gen, ctxt);
    }

    @Test
    public void testSerialize_withJsonSerializable() throws IOException {
        // Arrange
        JsonSerializable serializableMock = mock(JsonSerializable.class);
        POJONode node = new POJONode(serializableMock);
        JsonGenerator gen = mock(JsonGenerator.class);
        SerializerProvider ctxt = mock(SerializerProvider.class);

        // Act
        node.serialize(gen, ctxt);

        // Assert
        verify(serializableMock).serialize(gen, ctxt);
        verifyNoInteractions(gen);
    }

    @Test
    public void testSerialize_withStandardPojo() throws IOException {
        // Arrange
        TestPojo pojo = new TestPojo();
        POJONode node = new POJONode(pojo);
        JsonGenerator gen = mock(JsonGenerator.class);
        SerializerProvider ctxt = mock(SerializerProvider.class);

        // Act
        node.serialize(gen, ctxt);

        // Assert
        verify(gen).writeObject(pojo);
        verifyNoInteractions(ctxt);
    }

    @Test(expected = IOException.class)
    public void testSerialize_throwsIOException() throws IOException {
        // Arrange
        TestPojo pojo = new TestPojo();
        POJONode node = new POJONode(pojo);
        JsonGenerator gen = mock(JsonGenerator.class);
        SerializerProvider ctxt = mock(SerializerProvider.class);

        doThrow(new IOException("Simulated error")).when(gen).writeObject(any());

        // Act
        node.serialize(gen, ctxt);
    }
}
